"""ARENA u01 的 10 道测验（沿用旧版，题目没有改）"""
from unitlib import Q
QUIZ = [
  Q('在 3Blue1Brown 的手写数字网络里，输入层为什么正好有 784 个神经元？', ['输入图片是 28×28 像素，每个像素对应一个神经元', '784 是实验中效果最好的数量', '训练集里有 784 张图片', '网络要区分 784 个类别'], 0, '$28 \\times 28 = 784$。输入层每个神经元的激活值就是一个像素的灰度值，所以输入层的大小由输入数据决定，不是调出来的超参数。'),
  Q('一个隐藏层神经元的激活值是怎么算出来的？', ['上一层所有激活值直接相加', '对上一层激活值做加权和、加上偏置，再经过激活函数', '训练开始时随机设定，之后保持不变', '由输出层反向推出来'], 1, '$a_j = \\sigma(\\sum_k w_{jk} a_k + b_j)$：先加权和，再加偏置，最后经过激活函数。随机初始化的是**权重和偏置**，不是激活值；激活值每次输入新图片都会重新计算。'),
  Q('**偏置 (bias)** 的作用最接近下面哪一项？', ['决定这个神经元关注上一层的哪些神经元', '把输出压缩到 0 到 1 之间', '调整加权和要达到多大，这个神经元才会明显激活', '决定网络有多少层'], 2, '偏置就是一个门槛（阈值）的平移量。「关注哪些神经元」是**权重**的作用，「压缩到 0–1」是 **Sigmoid 激活函数**的作用。'),
  Q("一层网络从 784 个神经元连到 16 个神经元，写成 $\\mathbf{a}' = \\sigma(W\\mathbf{a} + \\mathbf{b})$，权重矩阵 $W$ 的形状是？", ['784 × 16', '16 × 784', '784 × 784', '16 × 16'], 1, "$\\mathbf{a}$ 是 784 × 1 的列向量，结果 $\\mathbf{a}'$ 要是 16 × 1，所以 $W$ 必须是 **16 × 784**：行数 = 本层神经元数，列数 = 上一层神经元数。"),
  Q('上一题这一层（784 → 16）一共有多少个参数？', ['12,544', '800', '13,002', '12,560'], 3, '权重 $784 \\times 16 = 12{,}544$，再加 16 个偏置，共 **12,560**。13,002 是**整个网络**（784 → 16 → 16 → 10）的参数总数。'),
  Q('如果把多层网络里所有的激活函数都去掉，会发生什么？', ['网络表达能力变得更强', '训练变得更准确', '整个网络等价于一个线性变换，叠多少层都只相当于一层', '网络无法进行计算'], 2, '线性变换的组合仍然是线性变换：$W_3 W_2 W_1$ 可以合并成一个矩阵。没有非线性，深度就失去了意义。'),
  Q('**代价函数 (cost function)** 的值越小，说明什么？', ['网络的参数越少', '网络的层数越多', '学习率越小', '网络在训练数据上的输出越接近正确答案'], 3, '代价函数衡量的是网络输出与正确答案之间的差距（在所有训练样本上取平均），越小表示在训练数据上越准。'),
  Q('梯度下降每一步朝哪个方向更新参数？', ['梯度方向', '随机方向', '负梯度方向', '让所有参数都变小的方向'], 2, '梯度指向代价函数**增加最快**的方向，所以要往反方向走：$\\theta \\leftarrow \\theta - \\eta \\nabla C$。'),
  Q('学习率 (learning rate) 设得太大，最可能出现什么情况？', ['在最低点附近来回震荡，甚至越训练越差', '学得太慢', '保证找到全局最小值', '网络的参数数量增加'], 0, '步子太大会跨过谷底、在两侧来回跳，严重时代价越来越大（发散）。「学得太慢」是学习率**太小**的问题。'),
  Q('相比 Sigmoid，**ReLU** 的一个主要优点是？', ['输出在 0 到 1 之间，可以当成概率', '在任何地方都可导', '可以输出负数', '在正区间导数恒为 1，能缓解梯度消失'], 3, 'Sigmoid 两端的导数接近 0，层数多了梯度会连乘到几乎消失；ReLU 在正区间导数为 1。另外几个选项都不对：输出在 0–1 之间的是 Sigmoid；ReLU 在 0 点不可导；ReLU 的输出不可能为负。'),
]
